<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Payslip · ANERP</title><script src="https://cdn.tailwindcss.com"></script></head><body class="min-h-screen bg-slate-100 p-5 text-slate-900"><main class="mx-auto max-w-2xl rounded-2xl bg-white p-7 shadow-sm"><div class="flex justify-between"><div><h1 class="text-2xl font-bold">ANERP</h1><p class="text-sm text-slate-500">Employee payslip</p></div><button onclick="window.print()" class="rounded-full bg-slate-100 px-4 py-2 text-sm print:hidden">Print</button></div><hr class="my-6"><div class="grid grid-cols-2 gap-4 text-sm"><div><p class="text-slate-500">Employee</p><b>{{ $line->employee->first_name }} {{ $line->employee->last_name }}</b><p>{{ $line->employee->employee_number }}</p></div><div><p class="text-slate-500">Pay period</p><b>{{ $line->run->period_start->format('d M Y') }} – {{ $line->run->period_end->format('d M Y') }}</b><p>Payment date: {{ $line->run->payment_date?->format('d M Y') ?? 'Not set' }}</p></div></div><div class="mt-7 space-y-3 text-sm"><div class="flex justify-between"><span>Base pay</span><b>K {{ number_format((float)$line->base_pay,2) }}</b></div><div class="flex justify-between"><span>Allowances</span><b>K {{ number_format((float)$line->allowances,2) }}</b></div><div class="flex justify-between"><span>Tax deduction</span><b>K {{ number_format((float)$line->tax_deduction,2) }}</b></div><div class="flex justify-between"><span>Other deductions</span><b>K {{ number_format((float)$line->other_deductions,2) }}</b></div><hr><div class="flex justify-between text-lg"><b>Net pay</b><b>K {{ number_format((float)$line->net_pay,2) }}</b></div></div><p class="mt-7 rounded-xl bg-amber-50 p-3 text-xs text-amber-900">{{ $line->calculation_note }}</p><p class="mt-6 text-xs text-slate-400">Payroll run {{ $line->run->run_number }} · {{ $line->run->currency }}</p></main></body></html>